class Solution {
public:
    bool isPalindrome(int x) {
        // Negative numbers are not palindrome
        if (x < 0) return false;
        // Numbers ending with 0 are not palindrome unless the number is 0
        if (x % 10 == 0 && x != 0) return false;

        long long rev = 0;
        int cur = x;
        while (cur > rev) {
            rev = rev * 10 + cur % 10;
            cur /= 10;
        }
        // For even length: cur == rev
        // For odd length: ignore the middle digit by rev/10
        return cur == rev || cur == rev / 10;
    }
};

